import sys

def max_similarity_score(n, m, A, B):
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    max_score = 0

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if A[i - 1] == B[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                score = 4 * dp[i][j] - i - j
                max_score = max(max_score, score)
            else:
                dp[i][j] = 0

    return max_score

def main():
    import sys
    input = sys.stdin.read().split()
    n, m = map(int, input[:2])
    A, B = input[2], input[3]
    print(max_similarity_score(n, m, A, B))

if __name__ == "__main__":
    main()
